import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';

interface KeywordMatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

export async function parseResumeAndCalculateMatch(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const jobDescription = typeof req.body.jobDescription === 'string' ? req.body.jobDescription : '';
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Simple keyword extraction heuristics from job description
    const rawKeywords = jobDescription
      .toLowerCase()
      .replace(/[^a-z0-9\+\#\.\s]/g, '')
      .split(/\s+ mộts+|,|\n/)
      .filter((w: string) => w.length > 2);

    const uniqueKeywords = Array.from(new Set<string>(rawKeywords));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    for (const kw of uniqueKeywords) {
      if (resumeText.includes(kw)) {
        matchedKeywords.push(kw);
      } else {
        missingKeywords.push(kw);
      }
    }

    const totalKeywordsChecked = uniqueKeywords.length;
    const matchScore = totalKeywordsChecked > 0 
      ? Math.round((matchedKeywords.length / totalKeywordsChecked) * 100)
      : 0;

    const result: KeywordMatchResult = {
      matchScore,
      matchedKeywords,
      missingKeywords,
      totalKeywordsChecked
    };

    res.status(200).json(result);
  } catch (error) {
    console.error('Error parsing PDF and scoring resume:', error);
    res.status(500).json({ error: 'Internal server error during resume parsing.' });
  }
}

import React, { useEffect, useState } from 'react';

interface AnimatedMatchScoreGaugeProps {
  score: number;
  size?: number;
  strokeWidth?: number;
}

export const AnimatedMatchScoreGauge: React.FC<AnimatedMatchScoreGaugeProps> = ({
  score,
  size = 160,
  strokeWidth = 12
}) => {
  const [animatedScore, setAnimatedScore] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimatedScore(score);
    }, 100);
    return () => clearTimeout(timer);
  }, [score]);

  const center = size / 2;
  const radius = center - strokeWidth;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (animatedScore / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 80) return 'text-emerald-500';
    if (s >= 50) return 'text-amber-500';
    return 'text-rose-500';
  };

  return (
    <div className="relative flex flex-col items-center justify-center p-4 bg-white dark:bg-slate-900 rounded-2xl shadow-xl">
      <svg width={size} height={size} className="transform -rotate-90">
        <circle
          cx={center}
          cy={center}
          r={radius}
          stroke="currentColor"
          strokeWidth={strokeWidth}
          className="text-slate-200 dark:text-slate-700"
          fill="transparent"
        />
        <circle
          cx={center}
          cy={center}
          r={radius}
          stroke="currentColor"
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          className={`transition-all duration-1000 ease-out ${getColor(animatedScore)}`}
          fill="transparent"
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
        <span className={`text-3xl font-extrabold ${getColor(animatedScore)}`}>
          {animatedScore}%
        </span>
        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 mt-1">
          Match Score
        </span>
      </div>
    </div>
  );
};
